```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("temperatury.txt");
    string dzien;
    int rano, wieczor;
    int mroz = 0, duzeRoznice = 0;
    int sumaRano = 0, cnt = 0;
    string maxDzien;
    int maxRoznica = 0;
    while (plik >> dzien >> rano >> wieczor) {
        if (rano < 0) mroz++;
        int roznica = wieczor - rano;
        if (roznica > 10) duzeRoznice++;
        sumaRano += rano;
        cnt++;
        if (roznica > maxRoznica) {
            maxRoznica = roznica;
            maxDzien = dzien;
        }
    }
    cout << "Dni z mrozem rano: " << mroz << endl;
    cout << "Dni z roznica > 10: " << duzeRoznice << endl;
    cout << fixed << setprecision(2);
    cout << "Srednia rano: " << (double)sumaRano / cnt << endl;
    cout << "Najwieksza roznica: " << maxDzien << " (" << maxRoznica << ")" << endl;
    return 0;
}
```

Weryfikacja:
- Mroz rano: Sroda(-2) = 1
- Roznice: Pon=7, Wt=7, Sr=10, Czw=7, Pt=11, Sob=12, Nd=9
- Roznica > 10: Piatek(11), Sobota(12) = 2
- Suma rano: 5+3-2+0+4+6+2 = 18
- Srednia: 18/7 = 2.5714... ≈ 2.57
- Max roznica: Sobota (12)
